#!/usr/bin/env bash
# gen-class-inventory.sh — concatenate every class-bearing library source into
# templates/templ-components-classes.txt, the ADR-0045 "class inventory" that
# module consumers @source instead of re-deriving scan machinery.
#
# Why a concatenation and not a curated class list: Tailwind's scanner extracts
# candidate tokens from ANY text; false positives cost nothing, while a
# class-detection heuristic WILL eventually miss a dynamically-composed class
# (lookup maps, utils.Class strings, wire attribute dialects). Complete and
# dumb beats curated and wrong. Generated by release.sh and guarded by
# utils.TestClassInventoryFreshness (regenerate → byte-compare) — do not edit
# the output by hand.
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
out="$root/templates/templ-components-classes.txt"
tmp="$(mktemp)"
trap 'rm -f "$tmp"' EXIT

# The 7 published modules' source trees — everything the scanner must see.
# Deliberately excluded: examples/, cmd/, website/, visualtest/, docs/,
# scripts/, tests (*_test.go), and generated files (*_templ.go).
dirs=(
  display
  feedback
  forms
  layout
  navigation
  recipes
  utils
  icons
  errorpage
  charts/echarts
  htmx
  datastar
)

{
  echo "# templ-components class inventory — GENERATED, do not edit."
  echo "# Regenerate: scripts/gen-class-inventory.sh (release.sh runs it; the"
  echo "# freshness guard utils.TestClassInventoryFreshness fails on drift)."
  echo "# Purpose (ADR-0045): a tracked, environment-independent scan corpus."
  echo "# Copy next to your app.css and add: @source \"./templ-components-classes.txt\";"
} > "$tmp"

for dir in "${dirs[@]}"; do
  # shellcheck disable=SC2044
  for file in $(cd "$root" && find "$dir" -type f \( -name '*.templ' -o -name '*.go' \) \
    ! -name '*_templ.go' ! -name '*_test.go' | LC_ALL=C sort); do
    {
      echo
      echo "# ── $file ─────────────────────────────────────────────"
      cat "$root/$file"
    } >> "$tmp"
  done
done

if [[ ! -s "$tmp" ]]; then
  echo "gen-class-inventory: generated EMPTY inventory — refusing to write" >&2
  exit 1
fi

# Atomic replace: never leave a truncated inventory behind.
mv "$tmp" "$out"
trap - EXIT
echo "class inventory: $out ($(wc -l < "$out") lines)"
